package io.github.luckolite.interpreter;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class OwnedFlagArbitrationOriginalTest {
 static final class Page {int w=400,h=300;byte[]l=new byte[w*h],g=new byte[w*h];Page(){Arrays.fill(g,(byte)255);for(int y:new int[]{108,122,136,150,164})rect(20,380,y,y,1);}void rect(int left,int right,int top,int bottom,int label){for(int y=top;y<=bottom;y++)for(int x=left;x<=right;x++){l[y*w+x]=(byte)label;g[y*w+x]=35;}}void head(int cx,int cy){for(int y=cy-6;y<=cy+6;y++)for(int x=cx-10;x<=cx+10;x++)if((x-cx)*(x-cx)/100d+(y-cy)*(y-cy)/36d<=1){l[y*w+x]=2;g[y*w+x]=(byte)(Math.abs(x-cx)<=2&&Math.abs(y-cy)<=2?240:50);}}void flag(int sx,int end,int dir){for(int d=0;d<=29;d++){int x=sx+Math.round(12*(float)Math.sin(Math.PI*d/29));for(int dx=0;dx<2;dx++){int y=end-dir*d;l[y*w+x+dx]=3;g[y*w+x+dx]=35;}}}List<ScoreNoteEvent> read(){var lc=l.clone();var gc=g.clone();var n=OmrScoreInterpreter.analyze(l,g,w,h,List.of(new MeasureRegion(.03f,.97f,.15f,.9f))).notes();assertArrayEquals(lc,l);assertArrayEquals(gc,g);return n;} }
 static List<ScoreNoteEvent> scene(String mode){Page p=new Page();p.head(180,150);if(!mode.equals("whole"))p.rect(189,190,94,150,3);if(mode.equals("opposedUp")||mode.equals("opposedDown")||mode.equals("opposedBoth")){p.rect(170,171,150,206,3);if(!mode.equals("opposedDown"))p.flag(190,94,-1);if(!mode.equals("opposedUp"))p.flag(170,206,1);}if(mode.equals("sameDirForeign")||mode.equals("sameDirBoth")){p.head(208,150);p.rect(217,218,94,150,3);p.flag(218,94,-1);if(mode.equals("sameDirBoth"))p.flag(190,94,-1);}if(mode.equals("owned"))p.flag(190,94,-1);if(mode.equals("tremolo")){for(int k=0;k<3;k++)for(int dx=-10;dx<=10;dx++)for(int dy=-2;dy<=2;dy++)p.rect(190+dx,190+dx,112+k*11+Math.round(-.3f*dx)+dy,112+k*11+Math.round(-.3f*dx)+dy,5);}return p.read();}
 @Test public void genuineStemlessWholeRemainsWhole(){var ns=scene("whole");assertEquals(1,ns.size());assertEquals(4,ns.get(0).unbeamedDurationBeats(),0);assertEquals(0,ns.get(0).beamCount());}
 @Test public void unflaggedHalfIsNeverShortened(){var ns=scene("half");assertEquals(1,ns.size());assertTrue(ns.get(0).unbeamedDurationBeats()>=2);assertEquals(0,ns.get(0).beamCount());}
 @Test public void foreignParallelFlagDoesNotShortenOwnHead(){var ns=scene("sameDirForeign");var own=ns.stream().min(Comparator.comparingDouble(ScoreNoteEvent::positionInMeasure)).orElseThrow();assertEquals(0,own.beamCount());assertTrue(own.unbeamedDurationBeats()>=2);}
}
